      demonstrate: {
        hint: '看一看：快捷键操作的动画演示',
        camera: { pos: [0, 3, 5], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const ground = new THREE.Mesh(
            new THREE.PlaneGeometry(8, 6),
            new THREE.MeshStandardMaterial({ color: 0xe8e8e8 })
          )
          ground.rotation.x = -Math.PI / 2
          scene.add(ground)

          const mesh = new THREE.Mesh(
            new THREE.BoxGeometry(0.8, 0.8, 0.8),
            new THREE.MeshStandardMaterial({ color: 0x42a5f5, roughness: 0.3 })
          )
          mesh.position.set(-2, 0.4, 0)
          scene.add(mesh)

          let t = 0
          let done = false
          const totalDuration = 6

          currentUpdateFn = (dt) => {
            if (done) return
            t += dt

            if (t < 1.5) {
              // W 移动：方块从左滑到右
              mesh.position.x = -2 + (t / 1.5) * 4
              mesh.material.color.setHex(0xef5350)
            } else if (t < 3) {
              // E 旋转
              mesh.position.x = 2
              mesh.rotation.y = ((t - 1.5) / 1.5) * Math.PI * 2
              mesh.material.color.setHex(0x66bb6a)
            } else if (t < 4.5) {
              // R 缩放
              mesh.rotation.y = 0
              const s = 0.8 + Math.sin(((t - 3) / 1.5) * Math.PI) * 0.5
              mesh.scale.setScalar(s)
              mesh.material.color.setHex(0xffa726)
            } else {
              // F 聚焦：归位
              mesh.scale.setScalar(1)
              mesh.position.set(0, 0.4, 0)
              mesh.material.color.setHex(0xab47bc)
            }

            if (t >= totalDuration && !done) {
              done = true
              mesh.position.set(0, 0.4, 0)
              mesh.rotation.set(0, 0, 0)
              mesh.scale.setScalar(1)
              mesh.material.color.setHex(0x42a5f5)
              markDone()
            }
          }

          return () => { done = true; currentUpdateFn = null }
        },
      },

