          scene.add(ground)

          const itemData = [
            { name: 'Player', color: 0x42a5f5, icon: '⚙️', desc: '分辨率/图标' },
            { name: 'Quality', color: 0x66bb6a, icon: '🎨', desc: '画面质量' },
          ]
          const shuffled = [...itemData].sort(() => Math.random() - 0.5)

          const meshes = []
          const positions = [-1.5, 1.5]
          shuffled.forEach((item, i) => {
            const mesh = new THREE.Mesh(
              new THREE.BoxGeometry(0.8, 0.8, 0.8),
              new THREE.MeshStandardMaterial({ color: item.color, roughness: 0.3 })
            )
            mesh.position.set(positions[i], 0.4, 0)
            mesh.userData = { name: item.name }
            scene.add(mesh)
            meshes.push(mesh)
          })

          const labelContainer = document.createElement('div')
          labelContainer.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5;'
          canvasRef?.value?.parentElement?.appendChild(labelContainer)
          const labelEls = shuffled.map(item => {
            const el = document.createElement('div')
            el.style.cssText = `
              position:absolute; text-align:center; pointer-events:none;
              background:rgba(255,255,255,0.92); border-radius:8px; padding:6px 10px;
              box-shadow:0 2px 8px rgba(0,0,0,0.1); font-size:12px; color:#555;
              transform:translate(-50%,-100%); margin-top:-8px; white-space:nowrap;
            `
            el.innerHTML = `<div style="font-size:16px;margin-bottom:2px">${item.icon}</div><div style="font-weight:500">${item.name}</div><div style="font-size:11px;color:#999">${item.desc}</div>`
            labelContainer.appendChild(el)
            return el
          })

          function updateLabels() {
            meshes.forEach((m, i) => {
              const pos = m.position.clone(); pos.y += 0.6; pos.project(camera)
              labelEls[i].style.left = ((pos.x * 0.5 + 0.5) * canvasRef.value.parentElement.clientWidth) + 'px'
              labelEls[i].style.top = ((-pos.y * 0.5 + 0.5) * canvasRef.value.parentElement.clientHeight) + 'px'
            })
          }

          const rc = new THREE.Raycaster()
          const mv = new THREE.Vector2()
          let done = false

          function onClick(e) {
            if (done) return
            const rect = canvasRef.value.getBoundingClientRect()
            mv.x = ((e.clientX - rect.left) / rect.width) * 2 - 1
            mv.y = -((e.clientY - rect.top) / rect.height) * 2 + 1
            rc.setFromCamera(mv, camera)
            const hits = rc.intersectObjects(meshes)
            if (!hits.length) return
            const hit = hits[0].object
            if (hit.userData.name === 'Player') {
              done = true
              hit.material.emissive = new THREE.Color(0x22aa22)
              hit.scale.setScalar(1.3)
              labelEls[meshes.indexOf(hit)].style.color = '#4caf50'
              markDone()
            } else {
              hit.material.emissive = new THREE.Color(0xaa2222)
              setTimeout(() => { hit.material.emissive = new THREE.Color(0x000000) }, 300)
            }
          }

          canvasRef.value.addEventListener('click', onClick)
          let raf
          const loop = () => { updateLabels(); if (!done) raf = requestAnimationFrame(loop) }
          loop()

          return () => { done = true; cancelAnimationFrame(raf); canvasRef.value?.removeEventListener('click', onClick); labelContainer.remove() }
