          scene.add(ball)

          let vx = 2
          let t = 0
          let done = false
          const totalDuration = 5

          currentUpdateFn = (dt) => {
            if (done) return
            t += dt

            ball.position.x += vx * dt
            if (ball.position.x > 2 || ball.position.x < -2) {
              vx = -vx
            }

            if (t >= totalDuration && !done) {
              done = true
              ball.position.set(-2, 0.2, 0)
              markDone()
            }
          }

          return () => { done = true; currentUpdateFn = null }
