          const labels = shuffled.map(item => {
            const el = document.createElement('div'); el.style.cssText = 'position:absolute;text-align:center;pointer-events:none;background:rgba(255,255,255,0.92);border-radius:8px;padding:6px 10px;box-shadow:0 2px 8px rgba(0,0,0,0.1);font-size:12px;color:#555;transform:translate(-50%,-100%);margin-top:-8px;white-space:nowrap;'
            el.innerHTML = `<div style="font-size:16px;margin-bottom:2px">${item.icon}</div><div style="font-weight:500">${item.name}</div><div style="font-size:11px;color:#999">${item.desc}</div>`; lc.appendChild(el); return el
          })
