          const ground = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshStandardMaterial({ color: 0xe8e8e8 }))
          ground.rotation.x = -Math.PI / 2; scene.add(ground)
          const speaker = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.5, 16), new THREE.MeshStandardMaterial({ color: 0x42a5f5 }))
          speaker.position.set(0, 0.25, 0); scene.add(speaker)
          const waves = []
          let t = 0, done = false, totalDuration = 4, waveTimer = 0
          currentUpdateFn = (dt) => {
            if (done) return; t += dt; waveTimer += dt
            if (waveTimer > 0.3) {
              waveTimer = 0
              const w = new THREE.Mesh(new THREE.RingGeometry(0.3, 0.35, 16), new THREE.MeshStandardMaterial({ color: 0x42a5f5, transparent: true, opacity: 0.6 }))
              w.position.set(0, 0.3, 0); w.rotation.x = -Math.PI / 2; w.userData.life = 0; scene.add(w); waves.push(w)
            }
            waves.forEach(w => { w.userData.life += dt; w.position.y += dt * 2; w.material.opacity = 0.6 - w.userData.life * 0.4; w.scale.setScalar(1 + w.userData.life) })
            for (let i = waves.length - 1; i >= 0; i--) { if (waves[i].userData.life > 1.5) { scene.remove(waves[i]); waves.splice(i, 1) } }
            if (t >= totalDuration && !done) { done = true; waves.forEach(w => scene.remove(w)); waves.length = 0; markDone() }
          }
