          ground.rotation.x = -Math.PI / 2; scene.add(ground)
          const cube1 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.5, 0.5), new THREE.MeshStandardMaterial({ color: 0x42a5f5 }))
          cube1.position.set(-1.5, 0.25, 0); scene.add(cube1)
          const cube2 = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.5, 0.5), new THREE.MeshStandardMaterial({ color: 0xef5350 }))
          cube2.position.set(1.5, 0.25, 0); scene.add(cube2)
          let t = 0, done = false, totalDuration = 4
