          currentUpdateFn = (dt) => { if (done) return; t += dt; if (t > 3 && t < 5) { const c = new THREE.Color().lerpColors(new THREE.Color(0x4488ff), new THREE.Color(0xff6644), (t - 3) / 2); template.material.color.copy(c); insts.forEach(m => m.material.color.copy(c)) } if (t >= 7 && !done) { done = true; markDone() } }
