          const names = ['蓝天', '晚霞', '星空']; let active = 0; let done = false; const sw = []; const labels = [lc];
          for (let i = 0; i < 3; i++) { const b = document.createElement('button'); b.textContent = names[i]; b.style.cssText = `padding:6px 14px;border-radius:6px;border:2px solid #555;background:#222;color:#fff;cursor:pointer;font-size:13px`; b.onclick = () => { active = i; updSw() }; lc.appendChild(b); sw.push(b) }
          canvasRef.value.parentElement.appendChild(lc);
          const skyColors = [0x87ceeb, 0xff6347, 0x1a1a3e];
          const ambColors = [0x6688aa, 0xaa6644, 0x222244];
          const ambIntens = [0.4, 0.3, 0.15];
          const sky = new THREE.Mesh(new THREE.SphereGeometry(10, 16, 16), new THREE.MeshBasicMaterial({ color: skyColors[0], side: THREE.BackSide })); scene.add(sky); labels.push(sky);
          const amb = new THREE.AmbientLight(ambColors[0], ambIntens[0]); scene.add(amb); labels.push(amb);
          const ground = new THREE.Mesh(new THREE.PlaneGeometry(6, 6), new THREE.MeshStandardMaterial({ color: 0x666666 })); ground.rotation.x = -Math.PI / 2; scene.add(ground);
          const box = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.2, 0.8), new THREE.MeshStandardMaterial({ color: 0xddddee })); box.position.set(0, 0.6, 0); scene.add(box);
          const sun = new THREE.DirectionalLight(0xffffff, 1); sun.position.set(3, 4, 2); scene.add(sun);
          function updSw() { sw.forEach((b, i) => { b.style.background = i === active ? '#4488ff' : '#222'; b.style.borderColor = i === active ? '#4488ff' : '#555' }); sky.material.color.setHex(skyColors[active]); amb.color.setHex(ambColors[active]); amb.intensity = ambIntens[active] }
