          const vignette = document.createElement('div'); vignette.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:150;opacity:0;background:radial-gradient(circle, transparent 50%, rgba(0,0,0,0.6) 100%)'; document.body.appendChild(vignette);
