          for (let i = 0; i < 3; i++) { const b = document.createElement('div'); b.textContent = opts[i]; b.style.cssText = 'padding:8px 16px;border-radius:8px;background:#222;color:#fff;font-size:14px;cursor:pointer;border:2px solid #555'; lc.appendChild(b); meshes.push(b); labels.push(b) }
          canvasRef.value.parentElement.appendChild(lc);
