          function updSw() { sw.forEach((b, i) => { b.style.background = i === active ? '#4488ff' : '#222'; b.style.borderColor = i === active ? '#4488ff' : '#555' }); table.rotation.z = active === 0 ? Math.PI / 2 : 0; texNote.style.display = active === 2 ? 'block' : 'none' }
