          for (const x of [-0.8, 0.8]) for (const z of [-0.4, 0.4]) { const leg = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.9, 0.15), new THREE.MeshStandardMaterial({ color: 0xb07a3c })); leg.position.set(x, 0.45, z); table.add(leg) }
