          const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.35, 1.6, 12), new THREE.MeshStandardMaterial({ color: 0x8a5a2c })); trunk.position.y = 0.8; scene.add(trunk); labels.push(trunk);
          const foliage = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 3), new THREE.MeshStandardMaterial({ color: 0x3fa34d, flatShading: true })); foliage.position.y = 2; scene.add(foliage); labels.push(foliage);
          const colBox = new THREE.Mesh(new THREE.BoxGeometry(0.9, 1.8, 0.9), new THREE.MeshBasicMaterial({ color: 0x44ff88, wireframe: true })); colBox.position.y = 0.9; colBox.visible = false; scene.add(colBox); labels.push(colBox);
          function updSw() { sw.forEach((b, i) => { b.style.background = i === active ? '#4488ff' : '#222'; b.style.borderColor = i === active ? '#4488ff' : '#555' }); foliage.geometry.dispose(); foliage.geometry = new THREE.IcosahedronGeometry(1, active === 1 ? 1 : 3); colBox.visible = active === 2 }
