        camera: { pos: [0, 2, 7], target: [0, 0.8, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          let t = 0; let done = false; let lodHi = true;
          const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.35, 1.6, 12), new THREE.MeshStandardMaterial({ color: 0x8a5a2c })); trunk.position.y = 0.8; scene.add(trunk);
          const foliageHi = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 4), new THREE.MeshStandardMaterial({ color: 0x3fa34d, flatShading: true })); foliageHi.position.y = 2; scene.add(foliageHi);
          const foliageLo = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), new THREE.MeshStandardMaterial({ color: 0x3fa34d, flatShading: true })); foliageLo.position.y = 2; foliageLo.visible = false; scene.add(foliageLo);
          currentUpdateFn = (dt) => { if (done) return; t += dt; const z = 5 + (Math.sin(t * 0.4) * 0.5 + 0.5) * 9; camera.position.z = z; const wantHi = z < 9; if (wantHi !== lodHi) { lodHi = wantHi; foliageHi.visible = lodHi; foliageLo.visible = !lodHi } if (t >= 12 && !done) { done = true; markDone() } }
          return () => { done = true; currentUpdateFn = null; scene.remove(trunk); scene.remove(foliageHi); scene.remove(foliageLo); camera.position.set(0, 2, 7) }
        },
