          const names = ['yield return null（等一帧）', 'WaitForSeconds（等 N 秒）', 'WaitForEndOfFrame（等帧尾）']; const sw = [];
          for (let i = 0; i < 3; i++) { const b = document.createElement('button'); b.textContent = names[i]; b.style.cssText = `padding:6px 14px;border-radius:6px;border:2px solid #555;background:#222;color:#fff;cursor:pointer;font-size:13px`; b.onclick = () => { active = i; updSw() }; lc.appendChild(b); sw.push(b) }
          canvasRef.value.parentElement.appendChild(lc); labels.push(lc);
          const track = new THREE.Mesh(new THREE.BoxGeometry(5, 0.1, 0.1), new THREE.MeshBasicMaterial({ color: 0x555555 })); track.position.set(0, 0.6, 0); scene.add(track); labels.push(track);
          const dot = new THREE.Mesh(new THREE.SphereGeometry(0.3, 16, 12), new THREE.MeshStandardMaterial({ color: 0xffd24a })); dot.position.set(-2.5, 0.6, 0); scene.add(dot); labels.push(dot);
          const pause = new THREE.Mesh(new THREE.TorusGeometry(0.4, 0.06, 8, 20), new THREE.MeshBasicMaterial({ color: 0xff4444 })); pause.position.set(0.5, 0.6, 0); pause.visible = false; scene.add(pause); labels.push(pause);
          function updSw() { sw.forEach((b, i) => { b.style.background = i === active ? '#4488ff' : '#222'; b.style.borderColor = i === active ? '#4488ff' : '#555' }); pause.visible = active === 1 }
