          const names = ['唯一 GameManager', '各处引用它']; const sw = [];
          for (let i = 0; i < 2; i++) { const b = document.createElement('button'); b.textContent = names[i]; b.style.cssText = `padding:6px 14px;border-radius:6px;border:2px solid #555;background:#222;color:#fff;cursor:pointer;font-size:13px`; b.onclick = () => { active = i; updSw() }; lc.appendChild(b); sw.push(b) }
