          const gm = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.2, 1.2), new THREE.MeshStandardMaterial({ color: 0x4488ff })); gm.position.set(0, 0.7, 0); scene.add(gm); labels.push(gm);
