          let t = 0; let done = false;
          const gm = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.2, 1.2), new THREE.MeshStandardMaterial({ color: 0x4488ff })); gm.position.set(0, 0.7, 0); scene.add(gm);
          const callers = [[-2.6, 0.4, 0], [2.6, 0.4, 0], [0, 1.8, 0]].map(p => { const m = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.6, 0.6), new THREE.MeshStandardMaterial({ color: 0xcccccc })); m.position.set(p[0], p[1], p[2]); scene.add(m); return m });
          currentUpdateFn = (dt) => { if (done) return; t += dt; const pulse = 0.5 + 0.5 * Math.sin(t * 3); callers.forEach(m => m.material.emissive.setHex(pulse > 0.5 ? 0x332200 : 0x000000)); gm.material.emissive.setHex(0x113355); if (t >= 10 && !done) { done = true; markDone() } }
