          currentUpdateFn = (dt) => { if (done) return; t += dt; const cycle = t % 4; const going = cycle < 1.5; const target = (Math.floor(t / 4) % 2 === 0) ? enemy : player; const tx = target.position.x; if (going) { bullet.position.x = -5 + (tx + 5) * Math.min(cycle / 1.5, 1); bullet.visible = true } else { bullet.visible = false; const hit = Math.abs(cycle - 1.6) < 0.1; target.material.emissive.setHex(hit ? 0x661111 : 0x000000) } if (t >= 10 && !done) { done = true; markDone() } }
          return () => { done = true; currentUpdateFn = null; scene.remove(enemy); scene.remove(player); scene.remove(bullet) }
