          canvasRef.value.parentElement.appendChild(lc);
          const onClick = (e) => { if (done) return; for (let i = 0; i < meshes.length; i++) { const r = meshes[i].getBoundingClientRect(); if (e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom) { if (i === 1) { done = true; meshes[i].style.background = '#4caf50'; meshes[i].style.borderColor = '#4caf50'; markDone() } else { meshes[i].style.background = '#aa2222'; setTimeout(() => { meshes[i].style.background = '#222' }, 400) } break } } }
          canvasRef.value.addEventListener('click', onClick);
          return () => { done = true; canvasRef.value?.removeEventListener('click', onClick); lc.remove() }
