          const barO = new THREE.Mesh(new THREE.BoxGeometry(2, 0.3, 0.3), new THREE.MeshBasicMaterial({ color: 0xff9933 })); barO.position.set(1.2, 0.6, 0); scene.add(barO);
          currentUpdateFn = (dt) => { if (done) return; t += dt; const paused = (t % 4) > 2; const real = (t % 4) / 4; const wG = Math.max(0.05, real * 2); barG.scale.x = wG; barG.position.x = -1.2 + (wG - 2) / 2; const wO = paused ? barO.scale.x : Math.max(0.05, real * 2); barO.scale.x = wO; barO.position.x = 1.2 + (wO - 2) / 2; barO.material.color.setHex(paused ? 0x884400 : 0xff9933); if (t >= 10 && !done) { done = true; markDone() } }
          return () => { done = true; currentUpdateFn = null; scene.remove(barG); scene.remove(barO) }
