          function updSw() { sw.forEach((b, i) => { b.style.background = i === active ? '#4488ff' : '#222'; b.style.borderColor = i === active ? '#4488ff' : '#555' }); blocks.forEach((m, i) => m.material.emissive.setHex(i === active ? 0x224400 : 0x000000)) }
