          const player = new THREE.Mesh(new THREE.CapsuleGeometry(0.4, 1, 6, 12), new THREE.MeshStandardMaterial({ color: 0x4488ff })); player.position.set(-2.4, 0.7, 0); scene.add(player);
          const enemy = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0xaa3333 })); enemy.position.set(1.2, 0.5, 0); scene.add(enemy);
          const bar = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.25, 0.25), new THREE.MeshBasicMaterial({ color: 0x44ff88 })); bar.position.set(1.2, 1.4, 0); scene.add(bar);
          currentUpdateFn = (dt) => { if (done) return; t += dt; const beat = (t * 0.8) % 1; const atk = beat < 0.2; player.material.emissive.setHex(atk ? 0x113344 : 0x000000); enemy.material.emissive.setHex(atk ? 0x661111 : 0x000000); const hp = Math.max(0.1, 1 - Math.floor(t / 1.25) * 0.25); bar.scale.x = hp; bar.position.x = 1.2 - (1 - hp) * 0.7; if (t >= 10 && !done) { done = true; markDone() } }
