          const tip = document.createElement('div')
          tip.textContent = '点击方块试一下'; tip.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:8px 14px;border-radius:10px;background:rgba(20,28,42,.8);color:#cdf;font:600 13px system-ui'
