          lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#cdf;font:600 13px system-ui'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let s = 0
          function upd() { lbl.textContent = s ? '状态：追踪（红）' : '状态：巡逻（蓝）'; enemy.material.color.set(s ? 0xff3333 : 0x4488ff); btn.textContent = '切到：' + (s ? '巡逻' : '追踪') }
          btn.onclick = () => { s = 1 - s; upd() }; upd()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
          return () => { done = true; btn.remove(); lbl.remove(); [ground, wall, enemy, ...dots].forEach(o => scene.remove(o)) }
