      demonstrate: {
        hint: '看敌人绕开墙巡逻，并在发现后切换为追踪。',
        camera: { pos: [4, 3.5, 6], target: [0, 0.6, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const ground = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), new THREE.MeshStandardMaterial({ color: 0x223044 }))
          ground.rotation.x = -Math.PI / 2; scene.add(ground)
          const wall = new THREE.Mesh(new THREE.BoxGeometry(0.5, 1.4, 3), new THREE.MeshStandardMaterial({ color: 0x884422 }))
          wall.position.set(0, 0.7, 0); scene.add(wall)
          const enemy = new THREE.Mesh(new THREE.CapsuleGeometry(0.3, 0.8, 4, 12), new THREE.MeshStandardMaterial({ color: 0x4488ff }))
          enemy.position.set(-3, 0.7, 1); scene.add(enemy)
          const path = [new THREE.Vector3(-3, 0.7, 1), new THREE.Vector3(3, 0.7, 1)]
          let seg = 0, t = 0
          currentUpdateFn = (dt) => {
            if (seg >= path.length - 1) { enemy.material.color.set(0xff3333); if (t > 4) markDone(); t += dt; return }
            t += dt / 1.5
            if (t >= 1) { t = 0; seg++; if (seg >= path.length - 1) { enemy.material.color.set(0xff3333); return } }
            enemy.position.lerpVectors(path[seg], path[seg + 1], t)
          }
          return () => { currentUpdateFn = null; [ground, wall, enemy].forEach(o => scene.remove(o)) }
        }
      },
