  'ai-9': {
    id: 'ai-9',
    title: 'A* 寻路算法原理',
    summary: 'A* 把地图切格，每格算 G（已走代价）+ H（估算到终点），每步挑 F=G+H 最小的格子探。',
    stages: {
      observe: {
        hint: '点击开关，看格子上的 G 值与 H 值如何共同决定优先级。',
        camera: { pos: [5, 5, 6], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const grid = new THREE.Group(); scene.add(grid)
          const cells = []
          for (let x = -3; x <= 3; x++) for (let z = -3; z <= 3; z++) {
            const m = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.2, 0.9), new THREE.MeshStandardMaterial({ color: 0x335577 }))
            m.position.set(x, 0, z); grid.add(m); cells.push(m)
          }
          const start = cells.find(c => c.position.x === -3 && c.position.z === -3)
          const end = cells.find(c => c.position.x === 3 && c.position.z === 3)
          start.material.color.set(0x33cc88); end.material.color.set(0xffaa33)
          const btn = document.createElement('button')
          btn.textContent = '高亮 F 最小路径格'; btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #4488ff;background:#222;color:#cdf;font:600 13px system-ui;cursor:pointer'
          const lbl = document.createElement('div')
          lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#cdf;font:600 13px system-ui'
          lbl.textContent = 'F = G(已走) + H(估算到终点)'; canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          btn.onclick = () => { cells.forEach(c => { if (c !== start && c !== end) c.material.color.set(0x335577) }); for (let i = 1; i <= 6; i++) { const c = cells.find(cc => cc.position.x === -3 + i && cc.position.z === -3 + i); if (c) c.material.color.set(0x4488ff) } }
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
          return () => { done = true; btn.remove(); lbl.remove(); while (grid.children.length) grid.remove(grid.children[0]); scene.remove(grid) }
        }
      },
      demonstrate: {
        hint: '看 A* 从起点逐格扩展，沿 F 最小的格子逼近终点。',
        camera: { pos: [5, 5, 6], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const grid = new THREE.Group(); scene.add(grid)
          const cells = []
          for (let x = -3; x <= 3; x++) for (let z = -3; z <= 3; z++) { const m = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.2, 0.9), new THREE.MeshStandardMaterial({ color: 0x335577 })); m.position.set(x, 0, z); grid.add(m); cells.push(m) }
          const start = cells.find(c => c.position.x === -3 && c.position.z === -3); const end = cells.find(c => c.position.x === 3 && c.position.z === 3)
          start.material.color.set(0x33cc88); end.material.color.set(0xffaa33)
          let t = 0, step = 0
          currentUpdateFn = (dt) => {
            t += dt
            if (t > 0.5 && step < 6) { step++; const c = cells.find(cc => cc.position.x === -3 + step && cc.position.z === -3 + step); if (c) c.material.color.set(0x4488ff) }
            if (step >= 6 && t > 4) markDone()
          }
          return () => { currentUpdateFn = null; while (grid.children.length) grid.remove(grid.children[0]); scene.remove(grid) }
        }
      },
      practice: {
        hint: '选正确项：A* 的 F = G + H 里，G 和 H 各自代表什么？',
        camera: { pos: [0, 1.4, 5], target: [0, 1, 0] },
        successTitle: '答对了',
        successText: 'G 是从起点走到当前格子的实际代价；H 是当前格子到终点的估算代价；F 是两者之和。',
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const opts = ['G 是这个格子到终点的估算代价，H 是从起点走到这格子的实际代价', 'G 是从起点走到这个格子的实际代价，H 是这个格子到终点的估算代价', 'G 是格子的宽度，H 是格子的高度']
          const correct = 1
          const box = document.createElement('div')
          box.style.cssText = 'position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);width:min(560px,90%);display:flex;flex-direction:column;gap:10px'
          canvasRef.appendChild(box)
          opts.map((t, i) => {
            const d = document.createElement('div')
            d.textContent = t; d.style.cssText = 'padding:12px 14px;border-radius:12px;border:1px solid #34507a;background:rgba(20,28,42,.82);color:#e8eef7;font:600 13px/1.4 system-ui;cursor:pointer'
            d.onclick = () => { if (i === correct) { d.style.background = '#1d5a33'; d.style.borderColor = '#33cc88'; markDone() } else { d.style.background = '#5a1d1d'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600) } }
            box.appendChild(d); return d
          })
          return () => { box.remove() }
        }
      },
    },
  },
