            const d = document.createElement('div')
            d.textContent = t; d.style.cssText = 'padding:12px 14px;border-radius:12px;border:1px solid #34507a;background:rgba(20,28,42,.82);color:#e8eef7;font:600 13px/1.4 system-ui;cursor:pointer'
