          for (let i = 0; i < 6; i++) { const b = new THREE.Mesh(new THREE.BoxGeometry(0.6, 1 + Math.random(), 0.6), new THREE.MeshStandardMaterial({ color: 0xff5555 })); b.position.set(-3 + i * 1.2, 0.5, 2); scene.add(b); bars.push(b) }
