          btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #4488ff;background:#222;color:#cdf;font:600 13px system-ui;cursor:pointer'
