          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let opt = false
          function upd() { bars.forEach(b => b.material.color.set(opt ? 0x33cc88 : 0xff5555)); lbl.textContent = opt ? '优化后：冷却/阈值/分时 → CPU 轻松（绿）' : '裸写：每帧感知+重算 → CPU 爆红'; btn.textContent = opt ? '切到：裸写' : '切到：优化' }
