          const minF = new THREE.Mesh(new THREE.BoxGeometry(3, 0.4, 0.4), new THREE.MeshBasicMaterial({ color: 0x33cc88 })); minF.position.set(0, 0.3, 0); scene.add(minF)
          let t = 0
