          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ef5350;background:#222;color:#fdd;font:600 13px system-ui;cursor:pointer'
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#fdd;font:600 13px system-ui'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let fired = false
          function upd() { const on = fired; listeners.forEach(m => m.material.color.set(on ? 0x66bb6a : 0x888888)); center.material.color.set(on ? 0xff7755 : 0xef5350); lbl.textContent = on ? '敌人死亡 → 三个系统同时响应 ✅' : '静止中…点按钮触发事件'; btn.textContent = on ? '重置' : '模拟敌人死亡' }
