  'arch-13': {
    id: 'arch-13',
    title: '命令模式与撤销',
    summary: '命令模式把操作封装成自带撤销的对象，配合双栈实现撤销/重做，配合序列实现回放——操作不再直接改状态，而是先记下来再执行。',
    stages: {
      observe: {
        hint: '点「撤销」看 MoveCommand 用记录的 from/to 把方块还原到操作前。',
        camera: { pos: [0, 2.5, 6], target: [0, 1, 0] },
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const box = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0x42a5f5 })); box.position.set(0, 0.6, 0); scene.add(box)
          const fromM = new THREE.Mesh(new THREE.SphereGeometry(0.12, 12, 12), new THREE.MeshStandardMaterial({ color: 0x888888 })); fromM.position.set(-2, 0.2, 0); scene.add(fromM)
          const toM = new THREE.Mesh(new THREE.SphereGeometry(0.12, 12, 12), new THREE.MeshStandardMaterial({ color: 0x888888 })); toM.position.set(2, 0.2, 0); scene.add(toM)
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #42a5f5;background:#222;color:#dff;font:600 13px system-ui;cursor:pointer'
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#dff;font:600 13px system-ui'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let moved = true
          function upd() { box.position.x = moved ? 2 : -2; lbl.textContent = moved ? '已执行 Move → 在 to（有 from 记录）' : '已撤销 → 回到 from ✅'; btn.textContent = moved ? '撤销' : '重新执行' }
          btn.onclick = () => { moved = !moved; upd() }; upd()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
          return () => { done = true; btn.remove(); lbl.remove(); [box, fromM, toM].forEach(o => scene.remove(o)) }
        }
      },
      demonstrate: {
        hint: '看方块移动到 to，撤销后精确回到 from。',
        camera: { pos: [0, 2.5, 6], target: [0, 1, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const box = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0x42a5f5 })); box.position.set(-2, 0.6, 0); scene.add(box)
          let t = 0, undoing = false
          currentUpdateFn = (dt) => { t += dt; if (!undoing) { const p = Math.min(1, t / 1.5); box.position.x = -2 + p * 4; if (t > 2) { undoing = true; t = 0 } } else { const p = Math.min(1, t / 1.2); box.position.x = 2 - p * 4; if (t > 1.4) markDone() } }
          return () => { currentUpdateFn = null; scene.remove(box) }
        }
      },
      practice: {
        hint: '选正确项：实现「撤销上一部操作」，命令对象至少必须包含什么信息？',
        camera: { pos: [0, 1.4, 5], target: [0, 1, 0] },
        successTitle: '答对了',
        successText: 'Undo 要把世界还原到操作之前的样子，所以命令必须自包含「撤销所需的全部现场」——比如移动命令要记 from 和 to，只有 to 没法撤。',
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const opts = ['只要目标物体的名字', '执行操作和执行前的现场（如起点位置），撤销时能还原', '操作的时间戳']
          const correct = 1
          const box = document.createElement('div'); box.style.cssText = 'position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);width:min(560px,90%);display:flex;flex-direction:column;gap:10px'
          canvasRef.appendChild(box)
          opts.map((t, i) => { const d = document.createElement('div'); d.textContent = t; d.style.cssText = 'padding:12px 14px;border-radius:12px;border:1px solid #34507a;background:rgba(20,28,42,.82);color:#e8eef7;font:600 13px/1.4 system-ui;cursor:pointer'; d.onclick = () => { if (i === correct) { d.style.background = '#1d5a33'; d.style.borderColor = '#33cc88'; markDone() } else { d.style.background = '#5a1d1d'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600) } }; box.appendChild(d); return d })
          return () => { box.remove() }
        }
      },
    },
  },

