          const sys = ['A', 'B', 'C'].map((t, i) => { const m = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.8, 0.8), new THREE.MeshStandardMaterial({ color: 0x888888 })); m.position.set((i - 1) * 2.2, 0.4, -1.5); scene.add(m); return m })
