          const camBox = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.6, 0.9), new THREE.MeshStandardMaterial({ color: 0x2e7d32 })); camBox.position.set(0, 2.2, 3); scene.add(camBox)
