          const intro = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.5, 0.8), new THREE.MeshStandardMaterial({ color: 0x888888 })); intro.position.set(-4, 2.5, 4); scene.add(intro)
          const fight = new THREE.Mesh(new THREE.BoxGeometry(0.8, 0.5, 0.8), new THREE.MeshStandardMaterial({ color: 0x888888 })); fight.position.set(3, 1.2, 2.5); scene.add(fight)
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
