          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
