          let t = 0
          currentUpdateFn = (dt) => { t += dt; cloud.rotation.y += dt * 2.2; cloud.children.forEach((m, i) => m.position.y = (i % 5) * 0.5 + Math.sin(t * 4 + i) * 0.4); if (t > 3.4) markDone() }
