          function upd() { eye.material.color.set(0xef5350); lbl.textContent = (selector ? 'Selector：玩家在视线→执行 A(追玩家)，B 跳过' : 'Sequence：要先 A 成功才到 B'); btn.textContent = selector ? '改：Sequence' : '改：Selector' }
          currentUpdateFn = (dt) => { t += dt; const inSight = Math.sin(t * 0.8) > 0; a.material.color.set(inSight ? 0x66bb6a : 0x888888); const bActive = selector ? !inSight : false; b.material.color.set(bActive ? 0x66bb6a : 0x888888); eye.position.z = inSight ? 1.5 : -1.5 }
