        camera: { pos: [0, 6, 13], target: [0, 1, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const swarm = new THREE.Group(); scene.add(swarm)
          const N = 40; const boids = []
          for (let i = 0; i < N; i++) { const m = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.6, 8), new THREE.MeshStandardMaterial({ color: 0x42a5f5 })); m.position.set((Math.random() - 0.5) * 6, 1, (Math.random() - 0.5) * 6); swarm.add(m); boids.push(m) }
          let t = 0
          currentUpdateFn = (dt) => { t += dt; const sepR = 1.6; boids.forEach((m, i) => { let dx = 0, dz = 0; boids.forEach((o, j) => { if (i === j) return; const ddx = m.position.x - o.position.x, ddz = m.position.z - o.position.z; const d = Math.hypot(ddx, ddz); if (d < sepR && d > 0.001) { dx += ddx / d; dz += ddz / d } }); m.position.x += dx * dt * 2; m.position.z += dz * dt * 2; m.position.x = Math.max(-6, Math.min(6, m.position.x)); m.position.z = Math.max(-6, Math.min(6, m.position.z)) }); if (t > 3.4) markDone() }
          return () => { currentUpdateFn = null; swarm.children.slice().forEach(o => { o.geometry.dispose(); o.material.dispose() }); scene.remove(swarm) }
        }
