          currentUpdateFn = (dt) => { t += dt; const k = (t % 4) / 4; ball.position.x = -3.5 + k * 7; ball.position.y = coll ? Math.max(1.1, 2 - (k < 0.5 ? k * 2 : 1 - (k - 0.5) * 2)) : 1.1 }
