          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let safe = true, t = 0
          function build() { while (platforms.children.length) platforms.remove(platforms.children[0]); let x = -4.5; while (x < 6) { const gap = safe ? (2 + Math.random() * 3) : (1 + Math.random() * 19); x += gap; const m = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.3, 1.6), new THREE.MeshStandardMaterial({ color: 0x66bb6a })); m.position.set(x, 0.15, 0); platforms.add(m) } }
          function upd() { lbl.textContent = safe ? '间隔锁 2~5 米 → 跳得过 ✅' : '1~20 米全随机 → 出现跳不过的断崖'; btn.textContent = safe ? '改：全随机' : '改：锁规则' }
          currentUpdateFn = (dt) => { t += dt; const k = (t % 4) / 4; player.position.x = -5 + k * 10; const y = safe ? (k < 0.12 ? Math.sin(k / 0.12 * Math.PI) * 0.7 : 0) : 0.5; player.position.y = 0.25 + Math.abs(Math.sin(k * Math.PI * 2)) * 0.6 }
          btn.onclick = () => { safe = !safe; build(); upd() }; build(); upd()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
          return () => { done = true; currentUpdateFn = null; btn.remove(); lbl.remove(); player.removeFromParent(); platforms.children.slice().forEach(o => { o.geometry.dispose(); o.material.dispose() }); scene.remove(platforms) }
