          canvasRef.appendChild(box)
          opts.map((t, i) => { const d = document.createElement('div'); d.textContent = t; d.style.cssText = 'padding:12px 14px;border-radius:12px;border:1px solid #34507a;background:rgba(20,28,42,.82);color:#e8eef7;font:600 13px/1.4 system-ui;cursor:pointer'; d.onclick = () => { if (i === correct) { d.style.background = '#1d5a33'; d.style.borderColor = '#33cc88'; markDone() } else { d.style.background = '#5a1d1d'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600) } }; box.appendChild(d); return d })
          return () => { box.remove() }
