          const enemies = Array.from({ length: 4 }, (_, i) => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.5, 16, 16), new THREE.MeshStandardMaterial({ color: 0xef5350 })); m.position.set(-1.5 + i * 1.6, 1, 0); scene.add(m); return m })
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let all = true, t = 0
          function upd() { lbl.textContent = all ? 'RaycastAll → 一枪穿一排，每个都掉血 ✅' : 'Raycast → 只打中第一个'; btn.textContent = all ? '改：只打第一个' : '改：穿一排' }
          currentUpdateFn = (dt) => { t += dt; const k = (t % 3) / 3; const n = all ? Math.floor(k * 4) : (k > 0.15 ? 1 : 0); enemies.forEach((m, i) => { m.material.color.set(i < n ? 0x666 : 0xef5350); m.scale.setScalar(i < n ? 0.3 : 1) }) }
          btn.onclick = () => { all = !all; upd() }; upd()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
          return () => { done = true; currentUpdateFn = null; btn.remove(); lbl.remove(); [gun, ...enemies].forEach(o => scene.remove(o)) }
