          const kids = Array.from({ length: 3 }, (_, i) => { const m = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.4, 0.3), new THREE.MeshStandardMaterial({ color: 0x66bb6a })); m.position.set((i - 1) * 0.7, 1.3, 0.25); scene.add(m); return m })
