          currentUpdateFn = (dt) => { t += dt; const cut = t % 4 < 2; player.position.x = -3 + (lock || !cut ? Math.sin(t) * 0.4 : Math.sin(t * 6) * 2); player.material.color.set(lock && cut ? 0x888888 : 0x42a5f5) }
