          const grid = new THREE.Mesh(new THREE.PlaneGeometry(3.8, 2.2), new THREE.MeshBasicMaterial({ color: 0x66bb6a, transparent: true, opacity: 0.35, side: THREE.DoubleSide })); grid.position.set(0, 0.67, 0); scene.add(grid)
          const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.3, 0.5, 12), new THREE.MeshStandardMaterial({ color: 0x42a5f5 })); scene.add(cup)
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let detect = true
          function upd() { grid.visible = detect; cup.material.color.set(detect ? 0x42a5f5 : 0x5a1d1d); lbl.textContent = detect ? '先平面检测 → 茶杯立在桌面上 ✅' : '直接随机放 → 飘在空气里'; btn.textContent = detect ? '改：随机放' : '改：先检测' }
          function place() { cup.position.set(0, detect ? 0.95 : 2.2, 0) }
          btn.onclick = () => { detect = !detect; upd(); place() }; upd(); place()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
