          const server = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0x66bb6a })); server.position.set(0, 1.4, 0); scene.add(server)
          const others = [2.5].map((x) => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.35, 12, 12), new THREE.MeshStandardMaterial({ color: 0xef5350 })); m.position.set(x, 1.4, 0); scene.add(m); return m })
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let serverRpc = true, t = 0
          function upd() { lbl.textContent = serverRpc ? '[ServerRpc] 客户端→服务器：先裁决 ✅' : '[ClientRpc] 服务器→全员广播'; btn.textContent = serverRpc ? '改：ClientRpc' : '改：ServerRpc' }
          currentUpdateFn = (dt) => { t += dt; const p = (t % 1.6) / 1.6; if (serverRpc) { client.material.color.set(p < 0.3 ? 0xffa726 : 0x42a5f5); server.material.color.set(p > 0.3 && p < 0.7 ? 0xffa726 : 0x66bb6a) } else { server.material.color.set(p < 0.3 ? 0xffa726 : 0x66bb6a); others[0].material.color.set(p > 0.3 && p < 0.7 ? 0xffa726 : 0xef5350) } }
          btn.onclick = () => { serverRpc = !serverRpc; upd() }; upd()
          let done = false; setTimeout(() => { if (!done) { done = true; markDone() } }, 12000)
