          currentUpdateFn = (dt) => { t += dt; const k = (t % 2.6) / 2.6; coin.position.x = -3 + k * 6; coin.position.y = 1 + (tween ? Math.sin(k * Math.PI) * 0.3 : 0); if (k > 0.95) coin.scale.setScalar(0.01) }
