          const player = new THREE.Mesh(new THREE.CapsuleGeometry(0.35, 1, 8, 16), new THREE.MeshStandardMaterial({ color: 0x42a5f5 })); player.position.set(-3, 0.9, 0); scene.add(player)
          const lbl = document.createElement('div'); lbl.style.cssText = 'position:absolute;left:50%;top:14px;transform:translateX(-50%);padding:6px 12px;border-radius:8px;background:rgba(20,28,42,.8);color:#e8eef7;font:600 13px system-ui'
          const btn = document.createElement('button'); btn.style.cssText = 'position:absolute;left:50%;bottom:18px;transform:translateX(-50%);padding:9px 16px;border-radius:10px;border:1px solid #ffa726;background:#222;color:#ffe;font:600 13px system-ui;cursor:pointer'
          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let good = true, t = 0
          function upd() { lbl.textContent = good ? '完整状态机：混合树+Jump+Attack，切换顺滑 ✅' : '过渡 Has Exit Time 全错 → 闪断/跳不起来'; btn.textContent = good ? '改：坏过渡' : '改：完整状态机' }
          currentUpdateFn = (dt) => { t += dt; const k = (t % 4) / 4; player.position.x = -3 + k * 6; player.position.y = 0.9 + (k > 0.3 && k < 0.55 ? Math.sin((k - 0.3) / 0.25 * Math.PI) * 1.2 : 0) }
          btn.onclick = () => { good = !good; upd() }; upd()
