          currentUpdateFn = (dt) => { t += dt; const k = (t % 3) / 3; fruit.position.y = 2.5 - k * 3; fruit.position.x = Math.sin(k * Math.PI) * 1; const hitB = fruit.position.y < 0.9; const hitZ = fruit.position.y < -0.2; fruit.material.color.set(hitB ? 0x33cc88 : hitZ ? 0x5a1d1d : 0xff6b6b) }
