          currentUpdateFn = (dt) => { t += dt; const k = (t % 3.5) / 3.5; const transfer = k > 0.4; world.children.forEach((m, i) => m.visible = snapshot ? true : !(transfer && i < 6)); host.visible = !transfer; newHost.material.color.set(transfer ? 0xffa726 : 0xffd54f) }
