          canvasRef.appendChild(lbl); canvasRef.appendChild(btn)
          let prefer = true, t = 0
          function upd() { lbl.textContent = prefer ? 'UDP：丢了旧包就用新包 → 实时 ✅' : 'TCP：丢包重传旧位置 → 堵住新位置'; btn.textContent = prefer ? '改：TCP' : '改：UDP' }
          currentUpdateFn = (dt) => { t += dt; const k = (t % 3) / 3; const p = prefer ? k : (Math.floor(k * 6) / 6); udp.position.x = -2 + (prefer ? 0 : Math.sin(t * 5) * 0.4); tcp.position.x = 2 + (prefer ? Math.sin(t * 5) * 0.4 : 0); udp.scale.x = prefer ? 1 + Math.sin(t * 8) * 0.1 : 1; tcp.scale.x = prefer ? 1 : 1 + Math.sin(t * 3) * 0.15 }
          btn.onclick = () => { prefer = !prefer; upd() }; upd()
