          btn.textContent = '模拟：凌晨 2 点宕机'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#e74c3c;color:#fff;border:none;border-radius:8px;padding:10px 20px;font:600 14px sans-serif;cursor:pointer;z-index:30';
