          status.position.set(0, 2.4, 0); status.scale.set(4.6, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
          btn.textContent = '查留存漏斗'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:10px 20px;font:600 14px sans-serif;cursor:pointer;z-index:30';
