          l1.position.set(-2.4, -1.2, 0); l1.scale.set(2, 0.6, 1); group.add(l1);
          const l2 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('碰撞'), transparent: true }));
          l2.position.set(2.4, -1.2, 0); l2.scale.set(2, 0.6, 1); group.add(l2);
          const order = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('[UpdateBefore] 1 → 2'), transparent: true }));
          order.position.set(0, 1.7, 0); order.scale.set(3.6, 0.6, 1); group.add(order);
          let t = 0, hit = false;
          currentUpdateFn = (dt) => {
            t += dt;
            if (!hit && t > 1.5) { hit = true; m1.material.color.set(0x2ecc71); }
            if (t > 3) m2.material.color.set(0x3a7bd5);
            if (t > 4.5) markDone();
          };
          return () => { currentUpdateFn = null; group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
