          const fLbl = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('SystemAPI.Query.foreach 简洁', '#ffd98a'), transparent: true }));
          fLbl.position.set(0, 2, 0); fLbl.scale.set(3.8, 0.6, 1); group.add(fLbl);
          const jLbl = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('IJobEntity：遍历=Job+Burst 性能拉满', '#8affb0'), transparent: true }));
          jLbl.position.set(0, -2, 0); jLbl.scale.set(4, 0.6, 1); group.add(jLbl);
          let t = 0, mode = 0;
          const btn = document.createElement('div');
          btn.textContent = '切到 IJobEntity'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:10px 22px;font:600 15px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
