          const lC = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('Job C'), transparent: true }));
          lC.position.set(0, -1.5, 0); lC.scale.set(1.8, 0.55, 1); group.add(lC);
          const lD = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('Job D'), transparent: true }));
