          const d1 = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          d1.position.set(-2.6, 0.6, 0); group.add(d1);
          const d2 = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          d2.position.set(-2.6, -0.6, 0); group.add(d2);
          const bad = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0xff5566 }));
          bad.position.set(2.6, 0, 0); group.add(bad);
          const l1 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('可 Burst ✓', '#8affb0'), transparent: true }));
          l1.position.set(-2.6, 1.5, 0); l1.scale.set(2.2, 0.55, 1); group.add(l1);
          const l2 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('可测试 ✓', '#8affb0'), transparent: true }));
          l2.position.set(-2.6, -1.5, 0); l2.scale.set(2.2, 0.55, 1); group.add(l2);
          const l3 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('Job 里直接读输入 ✗', '#ff8a8a'), transparent: true }));
          l3.position.set(2.6, -1.5, 0); l3.scale.set(3, 0.55, 1); group.add(l3);
          let t = 0;
          currentUpdateFn = (dt) => {
            t += dt;
            [d1, d2].forEach(m => m.scale.setScalar(1 + Math.abs(Math.sin(t * 3)) * 0.1));
            if (t > 4.2) markDone();
          };
          return () => { currentUpdateFn = null; group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
