  'ecs-18': {
    id: 'ecs-18', title: 'ECS 性能对比', summary: '数据量小时传统反而更快——ECS 有启动/结构开销，优势要等数据量上来（万级）才显现。',
    stages: {
      observe: {
        hint: '拖动数据量滑块，看「传统」与「ECS」耗时曲线交叉点。',
        camera: { pos: [0, 2.4, 7], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const group = new THREE.Group(); scene.add(group);
          function mkLabel(t, color = '#b9d2ff') {
            const c = document.createElement('canvas'); c.width = 460; c.height = 84;
            const ctx = c.getContext('2d');
            ctx.fillStyle = '#1c2634'; ctx.fillRect(0, 0, 460, 84);
            ctx.fillStyle = color; ctx.font = 'bold 28px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText(t, 230, 42);
            return new THREE.CanvasTexture(c);
          }
          const trad = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0xffaa33 }));
          trad.position.set(-2, 0, 0); group.add(trad);
          const ecs = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0x2ecc71 }));
          ecs.position.set(2, 0, 0); group.add(ecs);
          const tLbl = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('传统'), transparent: true }));
          tLbl.position.set(-2, -1.4, 0); tLbl.scale.set(1.8, 0.6, 1); group.add(tLbl);
          const eLbl = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('ECS'), transparent: true }));
          eLbl.position.set(2, -1.4, 0); eLbl.scale.set(1.8, 0.6, 1); group.add(eLbl);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('数据量 100：传统更快', '#ffd98a'), transparent: true }));
          status.position.set(0, 1.9, 0); status.scale.set(4.4, 0.7, 1); group.add(status);
          const slider = document.createElement('input');
          slider.type = 'range'; slider.min = 100; slider.max = 100000; slider.step = 100; slider.value = 100;
          slider.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);width:300px;z-index:30;accent-color:#3a7bd5';
          canvasRef.appendChild(slider);
          slider.oninput = () => {
            const n = parseInt(slider.value);
            const tRatio = Math.log10(n) / 2.2;
            const eRatio = (Math.log10(n) - 2) / 2.2;
            trad.scale.setScalar(0.4 + tRatio);
            ecs.scale.setScalar(Math.max(0.3, 0.4 + eRatio * 1.6));
            const faster = n < 1000 ? '传统更快' : (n < 10000 ? '接近持平' : 'ECS 拉开差距');
            status.material.map = mkLabel('数据量 ' + n + '：' + faster, n > 10000 ? '#8affb0' : '#ffd98a'); status.material.needsUpdate = true;
            if (n > 30000) setTimeout(() => { if (parseInt(slider.value) > 30000) markDone(); }, 1200);
          };
          return () => { slider.remove(); group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
        },
      },
      demonstrate: {
        hint: '为什么 100 个时传统更快：ECS 有结构变更、调度、安全检查等固定开销，量小不划算。',
        camera: { pos: [0, 2.4, 7], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const group = new THREE.Group(); scene.add(group);
          function mkLabel(t) {
            const c = document.createElement('canvas'); c.width = 440; c.height = 84;
            const ctx = c.getContext('2d');
            ctx.fillStyle = '#1c2634'; ctx.fillRect(0, 0, 440, 84);
            ctx.fillStyle = '#b9d2ff'; ctx.font = 'bold 28px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText(t, 210, 42);
            return new THREE.CanvasTexture(c);
          }
          const fixed = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.9, 0.3), new THREE.MeshPhongMaterial({ color: 0xffaa33 }));
          fixed.position.set(0, 0.7, 0); group.add(fixed);
          const data = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.9, 0.3), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          data.position.set(0, -0.7, 0); group.add(data);
          const l1 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('固定开销：调度/安全检查', '#ffd98a'), transparent: true }));
          l1.position.set(0, 1.7, 0); l1.scale.set(3.8, 0.55, 1); group.add(l1);
          const l2 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('数据量越大越摊薄 → 万级优势显现', '#8affb0'), transparent: true }));
          l2.position.set(0, -1.7, 0); l2.scale.set(4.2, 0.55, 1); group.add(l2);
          let t = 0;
          currentUpdateFn = (dt) => {
            t += dt;
            fixed.scale.y = 0.9 - Math.min(t / 4, 1) * 0.45;
            data.scale.x = 1.4 + Math.min(t / 4, 1) * 0.8;
            if (t > 4.4) markDone();
          };
          return () => { currentUpdateFn = null; group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
        },
      },
      practice: {
        hint: '同一份逻辑传统版和 ECS 版对比，数据量只有 100 时传统版反而更快，这说明？',
        camera: { pos: [0, 2, 6], target: [0, 0, 0] },
        successTitle: '答对了', successText: '数据量太小差距没拉开，且 ECS 有启动/结构开销——ECS 的优势要等数据量上来（万级）才显现。',
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const box = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.4, 1.4), new THREE.MeshPhongMaterial({ color: 0xffaa33 }));
          scene.add(box);
          const opts = [
            ['ECS 不行，该放弃', 0],
            ['数据量太小差距没拉开，ECS 有启动开销，万级才显优势', 1],
            ['测试代码写错了', 2],
          ];
          const wrap = document.createElement('div');
          wrap.style.cssText = 'position:absolute;left:50%;top:70%;transform:translateX(-50%);display:flex;flex-direction:column;gap:8px;z-index:30';
          canvasRef.appendChild(wrap);
          opts.forEach(([l, i]) => {
            const d = document.createElement('div');
            d.textContent = l; d.style.cssText = 'background:rgba(20,28,42,.82);border:1px solid #34507a;color:#d6e4ff;border-radius:8px;padding:9px 18px;font:500 13px sans-serif;cursor:pointer;min-width:420px;text-align:center';
            d.onclick = () => {
              if (i === 1) { d.style.background = '#1e8e4e'; d.style.borderColor = '#2ecc71'; wrap.childNodes.forEach(n => n.style.pointerEvents = 'none'); markDone(); }
              else { d.style.background = '#a63a44'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600); }
            };
            wrap.appendChild(d);
          });
          return () => { wrap.remove(); box.geometry.dispose(); box.material.dispose(); scene.remove(box); };
        },
      },
    },
  },

