          btn.textContent = '切到 if 写死判断'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:9px 18px;font:600 13px sans-serif;cursor:pointer;z-index:30';
