            btn.textContent = mode ? '切回可读设计' : '切到无懈可击';
            status.material.map = mkLabel(mode ? '无懈可击：玩家无从下手 ✗' : '可读设计：前摇预警 + 弱点 + 失败有交代 ✓', mode ? '#ff8a8a' : '#8affb0'); status.material.needsUpdate = true;
