          const enemy = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 0.6), new THREE.MeshPhongMaterial({ color: 0xff5566 }));
          enemy.position.set(-2.8, 0, 0); group.add(enemy);
          const player = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 0.6), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          player.position.set(2.8, 0, 0); group.add(player);
          const wall = new THREE.Mesh(new THREE.BoxGeometry(0.25, 1.6, 0.25), new THREE.MeshPhongMaterial({ color: 0x8899aa }));
          wall.position.set(0, 0, 0); group.add(wall);
          const fov = new THREE.Mesh(new THREE.ConeGeometry(0.7, 5.4, 24), new THREE.MeshPhongMaterial({ color: 0x2ecc71, transparent: true, opacity: 0.12 }));
          fov.rotation.z = Math.PI / 2; fov.position.set(-0.2, 0, -0.3); group.add(fov);
          const ray = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.06, 3), new THREE.MeshPhongMaterial({ color: 0xffaa33 }));
          ray.position.set(-0.6, 0, -0.3); group.add(ray);
