            status.material.map = mkLabel(mode ? '没遮挡检测：验收不过 ✗' : 'Raycast 挡住 + Gizmos 可视化验证 ✓', mode ? '#ff8a8a' : '#8affb0'); status.material.needsUpdate = true;
            fov.material.color.set(mode ? 0xff5566 : 0x2ecc71);
