        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const group = new THREE.Group(); scene.add(group);
          function mkLabel(t, color = '#b9d2ff') {
            const c = document.createElement('canvas'); c.width = 460; c.height = 84;
            const ctx = c.getContext('2d');
            ctx.fillStyle = '#1c2634'; ctx.fillRect(0, 0, 460, 84);
            ctx.fillStyle = color; ctx.font = 'bold 28px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText(t, 230, 42);
            return new THREE.CanvasTexture(c);
          }
          const stages = ['教学', '第一关', '第二关', '第三关'];
          const bars = stages.map((n, i) => {
            const h = [2.2, 0.6, 1.5, 1.8][i];
            const m = new THREE.Mesh(new THREE.BoxGeometry(0.9, h, 0.9), new THREE.MeshPhongMaterial({ color: i === 1 ? 0xff5566 : 0x3a7bd5 }));
            m.position.set(-2.7 + i * 1.8, h / 2, 0); group.add(m);
            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel(n, '#b9d2ff'), transparent: true }));
            sp.position.set(-2.7 + i * 1.8, -0.8, 0); sp.scale.set(2.2, 0.6, 1); group.add(sp);
            return m;
          });
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('「第一关太难」→ 先查遥测数据', '#ffd98a'), transparent: true }));
          status.position.set(0, 2.3, 0); status.scale.set(4.6, 0.7, 1); group.add(status);
          let t = 0, step = 0;
          const btn = document.createElement('div');
          btn.textContent = '看遥测 → 定位流失在「第一关」'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:9px 18px;font:600 13px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
          btn.onclick = () => {
            if (step === 0) {
              step = 1;
              bars[1].material.color.set(0xff5566); bars[1].scale.setScalar(1.3);
              status.material.map = mkLabel('定位：玩家死在第一关的跳跃处，只改跳跃参数', '#8affb0'); status.material.needsUpdate = true;
              setTimeout(() => markDone(), 1700);
            }
          };
          currentUpdateFn = (dt) => {
            t += dt;
            bars.forEach((m, i) => m.position.y = m.scale.y * 1.1 / 2 + Math.sin(t * 2 + i) * 0.03);
          };
          return () => { currentUpdateFn = null; btn.remove(); group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
        },
