          status.position.set(0, 1.9, 0); status.scale.set(4.6, 0.7, 1); group.add(status);
          let t = 0, mode = 0, done = false;
          const btn = document.createElement('div');
          btn.textContent = '加上 5 秒计时器'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#2ecc71;color:#fff;border:none;border-radius:8px;padding:10px 20px;font:600 14px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
