          box.position.set(-2, 0, 0); group.add(box);
          const check = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 0.7), new THREE.MeshPhongMaterial({ color: 0x2ecc71, transparent: true, opacity: 0 }));
          check.position.set(2, 0, 0); group.add(check);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('yield return null 推进 2 帧 → 断言', '#ffd98a'), transparent: true }));
          status.position.set(0, 1.8, 0); status.scale.set(4.6, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
