          timer.position.set(2.2, 0, 0); group.add(timer);
          const fill = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.13, 0.13), new THREE.MeshPhongMaterial({ color: 0xffaa33 }));
          fill.position.set(1.1, 0, 0); group.add(fill);
