          status.position.set(0, 1.9, 0); status.scale.set(4.8, 0.7, 1); group.add(status);
          let t = 0, paused = true, done = false;
          const btn = document.createElement('div');
          btn.textContent = '恢复 timeScale=1'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:10px 20px;font:600 14px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
