            const m = new THREE.Mesh(new THREE.BoxGeometry(0.5, h, 0.5), new THREE.MeshPhongMaterial({ color: 0x8899aa }));
            m.position.set((i - 2.5) * 0.7, h / 2, (j - 2.5) * 0.7);
