            d.textContent = l; d.style.cssText = 'background:rgba(20,28,42,.82);border:1px solid #34507a;color:#d6e4ff;border-radius:8px;padding:9px 18px;font:500 13px sans-serif;cursor:pointer;min-width:460px;text-align:center';
            d.onclick = () => {
              if (i === 0) { d.style.background = '#1e8e4e'; d.style.borderColor = '#2ecc71'; wrap.childNodes.forEach(n => n.style.pointerEvents = 'none'); markDone(); }
              else { d.style.background = '#a63a44'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600); }
            };
