          player.position.set(-2.2, 0, 0); group.add(player);
          const ground = new THREE.Mesh(new THREE.BoxGeometry(5.4, 0.2, 0.2), new THREE.MeshPhongMaterial({ color: 0x445566 }));
          ground.position.set(0, -1.3, 0); group.add(ground);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('小重力：下落慢吞吞，很飘 ✗', '#ff8a8a'), transparent: true }));
          status.position.set(0, 1.9, 0); status.scale.set(4.4, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
          btn.textContent = '调大 gravity → 手感干脆'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#2ecc71;color:#fff;border:none;border-radius:8px;padding:10px 18px;font:600 13px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
