          status.position.set(0, 2.3, 0); status.scale.set(4.4, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
          btn.textContent = 'Bounciness 调高 → 弹起来'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#2ecc71;color:#fff;border:none;border-radius:8px;padding:10px 18px;font:600 13px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
          let mode = 0, done = false;
