          const player = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 0.6), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          player.position.set(-2.4, 0, 0); group.add(player);
          const hp = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.2, 0.2), new THREE.MeshPhongMaterial({ color: 0x33475f }));
          hp.position.set(0, 1.8, 0); group.add(hp);
          const hpFill = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.13, 0.13), new THREE.MeshPhongMaterial({ color: 0x2ecc71 }));
          hpFill.position.set(-1.1, 1.8, 0); group.add(hpFill);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('点击走进火堆', '#ffd98a'), transparent: true }));
          status.position.set(0, 2.6, 0); status.scale.set(4, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
          btn.textContent = '走进火堆（OnTriggerStay）'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:9px 18px;font:600 13px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
