          status.position.set(0, 2, 0); status.scale.set(4.4, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
          btn.textContent = '加强入口提示（发光/色彩）'; btn.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);background:#3a7bd5;color:#fff;border:none;border-radius:8px;padding:10px 16px;font:600 13px sans-serif;cursor:pointer;z-index:30';
          canvasRef.appendChild(btn);
          let done = false;
          btn.onclick = () => {
            if (done) return; done = true;
            glow.material.opacity = 0.5;
            status.material.map = mkLabel('提示更明显 → 可发现性提升 ✓', '#8affb0'); status.material.needsUpdate = true;
            setTimeout(() => markDone(), 1900);
          };
          return () => { btn.remove(); group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
