  'uitoolkit-11': {
    id: 'uitoolkit-11', title: '自定义控件：C# 写控件', summary: '自定义进度条 fill 宽度跟随数值：把数值做成 Value 属性，set 里更新 fill 的宽度，并刷新文字。',
    stages: {
      observe: {
        hint: '拖动滑块，看 Value 属性 set 驱动 fill。',
        camera: { pos: [0, 2.4, 7], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const group = new THREE.Group(); scene.add(group);
          function mkLabel(t, color = '#b9d2ff') {
            const c = document.createElement('canvas'); c.width = 460; c.height = 84;
            const ctx = c.getContext('2d');
            ctx.fillStyle = '#1c2634'; ctx.fillRect(0, 0, 460, 84);
            ctx.fillStyle = color; ctx.font = 'bold 28px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText(t, 230, 42);
            return new THREE.CanvasTexture(c);
          }
          const bar = new THREE.Mesh(new THREE.BoxGeometry(3, 0.3, 0.2), new THREE.MeshPhongMaterial({ color: 0x33475f }));
          bar.position.set(0, 0, 0); group.add(bar);
          const fill = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.2, 0.1), new THREE.MeshPhongMaterial({ color: 0x2ecc71 }));
          fill.position.set(-1.5, 0, 0.1); group.add(fill);
          const pct = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('Value: 50%', '#ffd98a'), transparent: true }));
          pct.position.set(0, 1, 0); pct.scale.set(2.6, 0.55, 1); group.add(pct);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('Value 属性 set 里更新 fill 宽度 ✓', '#8affb0'), transparent: true }));
          status.position.set(0, -1.5, 0); status.scale.set(4.6, 0.7, 1); group.add(status);
          const slider = document.createElement('input');
          slider.type = 'range'; slider.min = 0; slider.max = 100; slider.step = 1; slider.value = 50;
          slider.style.cssText = 'position:absolute;left:50%;top:74%;transform:translateX(-50%);width:280px;z-index:30;accent-color:#2ecc71';
          canvasRef.appendChild(slider);
          slider.oninput = () => {
            const v = parseInt(slider.value);
            fill.scale.x = v / 100 * 3;
            pct.material.map = mkLabel('Value: ' + v + '%', '#ffd98a'); pct.material.needsUpdate = true;
            if (v > 90) setTimeout(() => markDone(), 1000);
          };
          return () => { slider.remove(); group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
        },
      },
      demonstrate: {
        hint: '自定义控件模式：属性（Value）→ set 访问器 → 更新子元素（fill 宽度 + 文字）——数据驱动视觉。',
        camera: { pos: [0, 2.4, 7], target: [0, 0, 0] },
        async setup(scene, camera, THREE, { markDone }) {
          const group = new THREE.Group(); scene.add(group);
          function mkLabel(t) {
            const c = document.createElement('canvas'); c.width = 460; c.height = 84;
            const ctx = c.getContext('2d');
            ctx.fillStyle = '#1c2634'; ctx.fillRect(0, 0, 460, 84);
            ctx.fillStyle = '#b9d2ff'; ctx.font = 'bold 28px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillText(t, 230, 42);
            return new THREE.CanvasTexture(c);
          }
          const names = ['Value 属性', 'set 更新', '视觉刷新'];
          const boxes = names.map((n, i) => {
            const m = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshPhongMaterial({ color: 0x33475f }));
            m.position.set(-2.6 + i * 2.6, 0, 0); group.add(m);
            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel(n, '#b9d2ff'), transparent: true }));
            sp.position.set(-2.6 + i * 2.6, -1.4, 0); sp.scale.set(2.6, 0.6, 1); group.add(sp);
            return m;
          });
          let t = 0;
          currentUpdateFn = (dt) => {
            t += dt;
            boxes.forEach((b, i) => { if (t > i * 1.3) b.material.color.set([0x3a7bd5, 0xffaa33, 0x2ecc71][i]); });
            if (t > 4.4) markDone();
          };
          return () => { currentUpdateFn = null; group.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) { if (o.material.map) o.material.map.dispose(); o.material.dispose(); } }); scene.remove(group); };
        },
      },
      practice: {
        hint: '自定义控件里搭了一个进度条 fill，想让它的宽度跟随一个 0~1 的数值变化，正确的做法是？',
        camera: { pos: [0, 2, 6], target: [0, 0, 0] },
        successTitle: '答对了', successText: '把数值做成 Value 属性，set 里更新 fill 的宽度，并刷新文字。',
        async setup(scene, camera, THREE, { markDone, canvasRef }) {
          const box = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.4, 1.4), new THREE.MeshPhongMaterial({ color: 0x3a7bd5 }));
          scene.add(box);
          const opts = [
            ['把数值存在静态变量里，别处改了直接生效', 0],
            ['把数值做成 Value 属性，set 里更新 fill 的宽度，并刷新文字', 1],
            ['在 Update 里每帧重新计算宽度', 2],
          ];
          const wrap = document.createElement('div');
          wrap.style.cssText = 'position:absolute;left:50%;top:70%;transform:translateX(-50%);display:flex;flex-direction:column;gap:8px;z-index:30';
          canvasRef.appendChild(wrap);
          opts.forEach(([l, i]) => {
            const d = document.createElement('div');
            d.textContent = l; d.style.cssText = 'background:rgba(20,28,42,.82);border:1px solid #34507a;color:#d6e4ff;border-radius:8px;padding:9px 18px;font:500 13px sans-serif;cursor:pointer;min-width:440px;text-align:center';
            d.onclick = () => {
              if (i === 1) { d.style.background = '#1e8e4e'; d.style.borderColor = '#2ecc71'; wrap.childNodes.forEach(n => n.style.pointerEvents = 'none'); markDone(); }
              else { d.style.background = '#a63a44'; d.style.borderColor = '#ff5566'; setTimeout(() => { d.style.background = 'rgba(20,28,42,.82)'; d.style.borderColor = '#34507a' }, 600); }
            };
            wrap.appendChild(d);
          });
          return () => { wrap.remove(); box.geometry.dispose(); box.material.dispose(); scene.remove(box); };
        },
      },
    },
  },

