          l1.position.set(-2.6, -1.5, 0); l1.scale.set(2.4, 0.6, 1); group.add(l1);
          const l2 = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('世界空间面板（1.5~3m）', '#8affb0'), transparent: true }));
          l2.position.set(0.5, -1.5, 0); l2.scale.set(3.2, 0.6, 1); group.add(l2);
          const ray = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.05, 0.05), new THREE.MeshPhongMaterial({ color: 0x2ecc71, transparent: true, opacity: 0.6 }));
