          anchor.position.set(0.4, -0.4, 0.3); group.add(anchor);
          const status = new THREE.Sprite(new THREE.SpriteMaterial({ map: mkLabel('点击：保存锚点 ID → 下次按 ID 加载', '#ffd98a'), transparent: true }));
          status.position.set(0, 2, 0); status.scale.set(4.8, 0.7, 1); group.add(status);
          const btn = document.createElement('div');
